// Lens profiles: the lensfun camera and lens table, and the lookup that turns
// the camera, lens, focal length, aperture, and focus distance of the open frame
// into the coefficients of the distortion, TCA, and vignetting models.
//
// The models and their coefficients are lensfun's, as documented in its
// lensfun.h. The database is a JSON copy of lensfun's XML files, generated by
// tools/lensdb/lensdb.py. The matching rules follow lensfun and darktable: the
// camera mount has to agree, a maker matches when one normalised string
// contains the other, and a model has to match after normalisation.
#pragma once

#include <string>

// The correction model the coefficients belong to. A value of None means the
// database has no calibration for that correction, and the effect leaves it
// alone.
enum class LensModel { None = 0, Poly3, Poly5, PtLens, TcaLinear, TcaPoly3, VignettingPa };

// Coefficients of one lens at one focal length, already interpolated between the
// calibrations that bracket it. Radius r is normalised so the image corner is 1.
struct LensProfile {
  // Distortion: r_d = r_u * f(r_u). Poly3 and poly5 keep their k terms in
  // terms[0..1]; ptlens keeps a, b, c in terms[0..2].
  LensModel distortion = LensModel::None;
  double distortionTerms[3] = {0.0, 0.0, 0.0};

  // TCA: r_d = r_u * f(r_u) per channel, red and blue. Green never moves.
  // Poly3 keeps v, c, b in slot 0, 1, 2; linear keeps k in slot 0.
  LensModel tca = LensModel::None;
  double tcaRed[3] = {1.0, 0.0, 0.0};
  double tcaBlue[3] = {1.0, 0.0, 0.0};

  // Vignetting: C_d = C_s * (1 + k1 r^2 + k2 r^4 + k3 r^6). One set of terms
  // for all three channels, which is how lensfun stores it.
  LensModel vignetting = LensModel::None;
  double vignettingTerms[3] = {0.0, 0.0, 0.0};

  // Crop factor of the camera the coefficients were matched for.
  double crop = 1.0;

  bool hasDistortion() const { return distortion != LensModel::None; }
  bool hasTca() const { return tca != LensModel::None; }
  bool hasVignetting() const { return vignetting != LensModel::None; }
  bool hasAnything() const { return hasDistortion() || hasTca() || hasVignetting(); }
};

// What the open frame says about its lens and how it was shot. A zero focal, the
// default, means the frame does not say.
struct LensShot {
  std::string cameraMaker;
  std::string cameraModel;
  std::string lensMaker;
  std::string lensModel;
  double focal = 0.0;     // mm
  double aperture = 0.0;  // f-number, 0 when unknown
  double distance = 0.0;  // metres, 0 when unknown
  double crop = 0.0;      // camera crop factor, 0 when the caller does not know it
};

// One camera row of the shipped table.
struct LensCamera {
  std::string maker;
  std::string model;
  std::string mount;
  double crop = 1.0;
};

// The camera row for a reported maker and model. Normalised matching, and the
// maker is only required when the table and the frame both give one.
bool lensCameraLookup(const std::string &maker, const std::string &model, LensCamera &out);

// Fills the profile for one shot. Returns false when the camera, the lens, or the
// focal length cannot be matched, and then the caller keeps its own values. The
// camera is matched first for the crop factor and the mount; the lens is matched
// on maker, model, and mount.
//
// The distortion and TCA coefficients are interpolated linearly between the
// calibrations that bracket the focal length and clamped outside them. The
// vignetting coefficients are interpolated on the same focal axis and then on
// the aperture axis, and the row with the nearest focus distance is used.
bool lensProfileLookup(const LensShot &shot, LensProfile &out);
